package com.stackgen.metadataservice.controller;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class ExceptionHandler { @ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Map<String,Object>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"error","BAD_REQUEST","message",e.getMessage()));} @ExceptionHandler(Exception.class) public ResponseEntity<Map<String,Object>> other(Exception e){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("timestamp",Instant.now(),"error","INTERNAL_SERVER_ERROR","message",e.getMessage()==null?"Unexpected error":e.getMessage()));} }
